        $payload=['conversation'=>$conversation,'recipient'=>$guest,'page_id'=>'123','instagram_id'=>'456','connection_id'=>\Kulturhus\Native\Integration\Accounts::binding($account),'messages'=>[$original]];\Kulturhus\Native\Shared\Db::run($db,'INSERT INTO native_social_inbox VALUES(?,?,?,?,?,UTC_TIMESTAMP())',[$access->club(),$thread,$channel,$box->seal('social-inbox:'.$access->club().':'.$thread,$payload),$date]);$attention->observe($access,$channel,'message',$conversation,[$original],true);
        $put($conversation,['id'=>$conversation,'participants'=>['data'=>[['id'=>$guest],['id'=>$sender]]],'is_owner'=>true]);$put($message,['id'=>$message,'message'=>$original['text'],'created_time'=>str_replace(' ','T',$date).'+0000','from'=>['id'=>$guest],'to'=>['data'=>[['id'=>$sender]]]]);
        $items[$channel]=['thread'=>$thread,'attention'=>substr(hash('sha256',$access->club().':'.$channel.':message:'.$conversation.':'.$message),0,32)];
        $parent=$channel==='facebook'?'123_880':'178880';$comment='own_browser_comment_'.$channel;$text='Own original browser comment '.$channel;
