        $attention->observe($access,$channel,'comment',$parent,[['id'=>$comment,'text'=>$text,'name'=>'Own commenter '.$channel,'title'=>'Own comment post']],true);$put($comment,['id'=>$comment,'message'=>$text,'text'=>$text,'can_comment'=>true,'hidden'=>false,'is_hidden'=>false]);$items[$channel]['comment']=substr(hash('sha256',$access->club().':'.$channel.':comment:'.$parent.':'.$comment),0,32);
    }
    for($i=0;$i<8;$i++){$conversation='own_short_browser_'.$i;$message='own_short_browser_message_'.$i;$thread=\Kulturhus\Native\Communication\MessageReplyProvider::threadId($access->club(),'facebook',$conversation);$original=['id'=>$message,'text'=>$i===0?'Senden':'Own short browser question '.$i.' · Senden <literal> ä🙂','from_name'=>$i===1?'Kommentare':'Own short browser '.$i,'from_id'=>'own_short_guest_'.$i,'incoming'=>true,'created_at'=>$date];$payload=['conversation'=>$conversation,'recipient'=>'own_short_guest_'.$i,'page_id'=>'123','instagram_id'=>'456','connection_id'=>\Kulturhus\Native\Integration\Accounts::binding($account),'messages'=>[$original]];\Kulturhus\Native\Shared\Db::run($db,'INSERT INTO native_social_inbox VALUES(?,?,?,?,?,UTC_TIMESTAMP())',[$access->club(),$thread,'facebook',$box->seal('social-inbox:'.$access->club().':'.$thread,$payload),$date]);$attention->observe($access,'facebook','message',$conversation,[$original],true);$attention->observe($access,'facebook','comment','123_880',[['id'=>'own_short_comment_'.$i,'text'=>$i===0?'Senden':'Own short browser comment '.$i.' · Senden <literal> ä🙂','name'=>$i===1?'Kommentare':'Own short browser '.$i,'title'=>'Own comment post']],false);}
