    $selected=getenv('DVM_CONVERSATION_PROFILE')?:'';if($selected!==''&&!in_array($selected,$allProfiles,true))throw new RuntimeException('Known owned conversation profile required.');$profiles=$selected!==''?[$selected]:$allProfiles;
    $input=['root'=>$root,'runtime'=>$runtime,'origin'=>'http://127.0.0.1:'.$port,'account'=>['actor'=>'own-human-browser-admin','native'=>$bridge->nativeActorId(),'token'=>$token],'items'=>$items,'accounts'=>$languageAccounts,'profiles'=>$profiles,'expected_provider_posts'=>count($profiles)*7];$file=$root.'/browser.json';file_put_contents($file,json_encode($input,JSON_THROW_ON_ERROR));chmod($file,0600);putenv('DVM_SOCIAL_HUMAN_BROWSER_FIXTURE='.$file);
